// Hesapları 3 gruba ayır + search query'leri hazırla
const accounts = $input.all().map(i => i.json);

// VIP: Tier 1-2, Global (AI labs + key people)
const vipAccounts = accounts.filter(a => (a.tier === 1 || a.tier === 2) && a.region !== 'TR');
const vipUsernames = vipAccounts.map(a => a.username);

// TR: region=TR (haber, spor, tech)
const trAccounts = accounts.filter(a => a.region === 'TR');
const trUsernames = trAccounts.map(a => a.username);

// VIP query batches (max 15 per query to avoid length limits)
const vipBatches = [];
for (let i = 0; i < vipUsernames.length; i += 15) {
  vipBatches.push(vipUsernames.slice(i, i + 15).map(u => `from:${u}`).join(' OR '));
}

const trBatches = [];
for (let i = 0; i < trUsernames.length; i += 15) {
  trBatches.push(trUsernames.slice(i, i + 15).map(u => `from:${u}`).join(' OR '));
}

// Keyword queries (community buzz)
const keywordQueries = [
  '"just released" (AI OR LLM OR model) min_faves:500',
  '"open source" (model OR LLM OR AI) min_faves:500',
  '"announcing" (from:AnthropicAI OR from:OpenAI OR from:GoogleDeepMind OR from:MistralAI OR from:MetaAI)',
  '"state of the art" (benchmark OR SOTA) min_faves:300',
  '(API OR SDK) launch (AI OR LLM) min_faves:500'
];

// Account lookup map
const accountMap = {};
for (const a of accounts) {
  accountMap[a.username.toLowerCase()] = a;
}

const batchId = crypto.randomUUID();

console.log(`Accounts: ${accounts.length} total | VIP: ${vipUsernames.length} | TR: ${trUsernames.length}`);
console.log(`Batches: VIP=${vipBatches.length} TR=${trBatches.length} KW=${keywordQueries.length}`);

return [{ json: {
  vipBatches,
  trBatches,
  keywordQueries,
  accountMap,
  batchId
} }];

// ═══ VIP Tweet Search (Tier 1-2 Global) ═══
// Xquik async job: POST start → poll GET → paginate

const XQUIK_KEY = $env.XQUIK_API_KEY;
const BASE = 'https://xquik.com/api/v1';
const { vipBatches, batchId } = $input.first().json;

async function xquikSearch(query, limit) {
  // 1. Start extraction
  let job;
  try {
    job = await $helpers.httpRequest({
      method: 'POST',
      url: `${BASE}/extractions`,
      headers: { 'x-api-key': XQUIK_KEY, 'Content-Type': 'application/json' },
      body: { toolType: 'tweet_search_extractor', searchQuery: query, resultsLimit: limit }
    });
  } catch (e) { console.log('Start error:', e.message); return []; }

  if (!job?.id) { console.log('No extraction ID:', JSON.stringify(job)); return []; }

  // 2. Poll until completed (max 120s)
  const start = Date.now();
  let data = null;
  while (Date.now() - start < 120000) {
    try {
      data = await $helpers.httpRequest({
        method: 'GET',
        url: `${BASE}/extractions/${job.id}`,
        headers: { 'x-api-key': XQUIK_KEY }
      });
    } catch (e) { console.log('Poll error:', e.message); return []; }

    const status = data?.job?.status || data?.status;
    if (status === 'completed') break;
    if (status === 'failed') { console.log('Job failed'); return []; }
    await new Promise(r => setTimeout(r, 2000));
  }
  if (!data) return [];

  // 3. Collect all pages
  let results = data.results || [];
  while (data?.hasMore && data?.nextCursor) {
    try {
      data = await $helpers.httpRequest({
        method: 'GET',
        url: `${BASE}/extractions/${job.id}`,
        headers: { 'x-api-key': XQUIK_KEY },
        qs: { after: data.nextCursor }
      });
      results = results.concat(data?.results || []);
    } catch (e) { break; }
  }
  return results;
}

// Run all VIP batches
let allTweets = [];
for (let i = 0; i < vipBatches.length; i++) {
  const tweets = await xquikSearch(vipBatches[i], 200);
  allTweets = allTweets.concat(tweets);
  console.log(`VIP batch ${i+1}/${vipBatches.length}: ${tweets.length} tweets`);
  if (i < vipBatches.length - 1) await new Promise(r => setTimeout(r, 1000));
}

console.log(`VIP total: ${allTweets.length} tweets`);
return [{ json: { tweets: allTweets, source: 'vip', batchId } }];

