// ═══ Normalize tweets → raw_signal format + URL dedup ═══

const inputs = $input.all().map(i => i.json);
const prepareData = $('Prepare Search Groups').first().json;
const accountMap = prepareData.accountMap || {};
const batchId = prepareData.batchId;

// Collect all tweets from all branches
let allTweets = [];
for (const input of inputs) {
  if (input.tweets && Array.isArray(input.tweets)) {
    const source = input.source || 'unknown';
    allTweets = allTweets.concat(input.tweets.map(t => ({ ...t, _source: source })));
  }
}

console.log(`Raw tweets from all branches: ${allTweets.length}`);

const seen = new Set();
const signals = [];
const cutoffMs = Date.now() - (72 * 60 * 60 * 1000);

for (const tweet of allTweets) {
  const tweetId = tweet.tweetId || tweet.id;
  const username = tweet.xUsername || tweet.author?.userName || '';
  const text = tweet.tweetText || tweet.text || '';

  // Temel filtreler
  if (!tweetId || !text) continue;
  if (text.startsWith('RT @')) continue;
  if (text.split(/\s+/).length < 4) continue;

  // URL dedup
  const url = `https://x.com/${username}/status/${tweetId}`;
  if (seen.has(url)) continue;
  seen.add(url);

  // Yaş filtresi (72h)
  const rawDate = tweet.tweetCreatedAt || tweet.createdAt;
  if (rawDate) {
    try { if (new Date(rawDate).getTime() < cutoffMs) continue; } catch (e) {}
  }

  // Hesap bilgisi
  const accInfo = accountMap[username.toLowerCase()] || {};
  let sourceName = 'twitter_keyword';
  if (tweet._source === 'vip') sourceName = accInfo.tier === 1 ? 'twitter_vip_t1' : 'twitter_vip_t2';
  else if (tweet._source === 'tr') sourceName = 'twitter_tr';

  signals.push({
    source_type: 'twitter',
    source_name: sourceName,
    niche: accInfo.niche || 'ai',
    title: text.replace(/\n/g, ' ').substring(0, 120),
    url,
    raw_data: {
      tweet_id: String(tweetId),
      tweet_text: text,
      author_username: username,
      author_name: tweet.xDisplayName || tweet.author?.name || '',
      followers_count: tweet.xFollowersCount || 0,
      like_count: tweet.likeCount || 0,
      retweet_count: tweet.retweetCount || 0,
      reply_count: tweet.replyCount || 0,
      view_count: tweet.viewCount || 0,
      tweet_created_at: rawDate,
      tier: accInfo.tier || 3,
      category: accInfo.category || 'community',
      region: accInfo.region || 'Global'
    },
    status: 'pending',
    batch_id: batchId
  });
}

console.log(`After normalize + dedup: ${signals.length} signals (from ${allTweets.length} raw)`);

return [{ json: {
  signals,
  totalRaw: allTweets.length,
  totalDeduped: signals.length,
  batchId
} }];

// ═══ Supabase Batch INSERT ═══

const SB_URL = $env.SUPABASE_URL;
const SB_KEY = $env.SUPABASE_SERVICE_KEY;
const BATCH_SIZE = 50;

const { signals, totalRaw, totalDeduped, batchId } = $input.first().json;
let totalInserted = 0;

for (let i = 0; i < signals.length; i += BATCH_SIZE) {
  const batch = signals.slice(i, i + BATCH_SIZE);
  try {
    await $helpers.httpRequest({
      method: 'POST',
      url: `${SB_URL}/rest/v1/raw_signals`,
      headers: {
        'apikey': SB_KEY,
        'Authorization': `Bearer ${SB_KEY}`,
        'Content-Type': 'application/json',
        'Prefer': 'resolution=ignore-duplicates,return=minimal'
      },
      body: batch
    });
    totalInserted += batch.length;
    console.log(`Batch ${Math.floor(i/BATCH_SIZE)+1}: ${batch.length} inserted`);
  } catch (e) {
    if (e.message?.includes('409') || e.message?.includes('duplicate')) {
      console.log(`Batch ${Math.floor(i/BATCH_SIZE)+1}: duplicates, skipped`);
    } else {
      console.log(`Insert error: ${e.message}`);
    }
  }
}

console.log(`Inserted: ${totalInserted} / ${signals.length}`);

return [{ json: {
  inserted: totalInserted,
  totalRaw,
  totalDeduped,
  batchId
} }];

// ═══ Success Summary ═══
const insertData = $('Supabase Insert').first().json;
const processData = $input.first().json;

return [{ json: {
  pipeline: 'twitter_radar',
  status: 'success',
  timestamp: new Date().toISOString(),
  signals_inserted: insertData?.inserted || 0,
  total_raw: insertData?.totalRaw || 0,
  total_deduped: insertData?.totalDeduped || 0,
  batch_id: insertData?.batchId || null,
  process_response: typeof processData === 'object' ? processData : { raw: String(processData) }
} }];

// ═══ No Signals Summary ═══
return [{ json: {
  pipeline: 'twitter_radar',
  status: 'no_signals',
  timestamp: new Date().toISOString(),
  message: 'No new tweets found after filtering'
} }];
